const fs = require('fs');
const path = require('path');
const action = (params.action || 'read').toLowerCase();
const p = params.path;
if (!p) throw new Error('params.path required');
if (action === 'read') {
  const max = Number(params.max_bytes ?? 102400);
  const buf = fs.readFileSync(p);
  const truncated = buf.length > max;
  return { content: buf.slice(0, max).toString('utf8'), bytes: buf.length, truncated };
}
if (action === 'write') {
  if (typeof params.content !== 'string') throw new Error('params.content (string) required for write');
  fs.writeFileSync(p, params.content, 'utf8');
  return { ok: true, bytes: Buffer.byteLength(params.content, 'utf8'), path: p };
}
if (action === 'append') {
  fs.appendFileSync(p, String(params.content ?? ''), 'utf8');
  return { ok: true, path: p };
}
if (action === 'list') {
  const dir = p;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  return { dir, entries: entries.slice(0, 500).map(e => ({ name: e.name, type: e.isDirectory() ? 'dir' : e.isSymbolicLink() ? 'symlink' : 'file' })), total: entries.length };
}
if (action === 'stat') {
  const s = fs.statSync(p);
  return { path: p, size: s.size, isFile: s.isFile(), isDirectory: s.isDirectory(), mtime: s.mtime, ctime: s.ctime, mode: s.mode.toString(8) };
}
if (action === 'exists') return { path: p, exists: fs.existsSync(p) };
if (action === 'delete') {
  if (params.confirm !== true) throw new Error('Set params.confirm=true to confirm delete');
  fs.rmSync(p, { recursive: true, force: true });
  return { ok: true, path: p, deleted: true };
}
throw new Error('Unknown action: ' + action);
